/* Pure calculations, shared by the interface and regression checks. */
(function(root){
'use strict';
const columns=['Transaction ID','Date','Customer ID','Gender','Age','Product Category','Quantity','Price per Unit','Total Amount'];
function parseCSV(text){let rows=[],row=[],v='',quoted=false; text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(v);v='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))rows.push(row);row=[];v='';}else v+=c;}if(quoted)throw Error('Unclosed quote in CSV.');row.push(v);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)throw Error('CSV needs a header and at least one transaction.');const heads=rows.shift().map(x=>x.trim());if(new Set(heads).size!==heads.length)throw Error('Duplicate column names.');for(const c of columns)if(!heads.includes(c))throw Error('Missing column: '+c);return validate(rows.map((r,i)=>{if(r.length!==heads.length)throw Error('Wrong number of fields on row '+(i+2));return Object.fromEntries(heads.map((h,j)=>[h,r[j].trim()]));}));}
function validate(rows){if(!rows.length)throw Error('No transactions found.');const ids=new Set();return rows.map((r,i)=>{for(const c of columns)if(r[c]===undefined||r[c]===null||String(r[c]).trim()==='')throw Error('Missing '+c+' on row '+(i+2));let d=String(r.Date);if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!Number.isFinite(Date.parse(d))||new Date(d).toISOString().slice(0,10)!==d)throw Error('Invalid date on row '+(i+2));let id=String(r['Transaction ID']);if(ids.has(id))throw Error('Duplicate transaction ID: '+id);ids.add(id);let q=Number(r.Quantity),p=Number(r['Price per Unit']),a=Number(r['Total Amount']),age=Number(r.Age);if(![q,p,a,age].every(Number.isFinite)||q<=0||!Number.isInteger(q)||p<=0||age<0||!Number.isInteger(age))throw Error('Invalid quantity, price, amount or age on row '+(i+2));if(Math.abs(q*p-a)>.01000001)throw Error('Quantity × price does not match total on row '+(i+2));return {id,date:d,customer:String(r['Customer ID']),gender:String(r.Gender),age,category:String(r['Product Category']),quantity:q,price:p,amount:a};});}
function filter(rows,start,end,cat){return rows.filter(r=>(!start||r.date>=start)&&(!end||r.date<=end)&&(!cat||r.category===cat));}
function stats(rows){const revenue=rows.reduce((s,r)=>s+r.amount,0),units=rows.reduce((s,r)=>s+r.quantity,0),count=rows.length;return{revenue,units,count,aov:count?revenue/count:0,unitValue:units?revenue/units:0};}
function group(rows,key){const m=new Map();for(const r of rows){const k=key(r);if(!m.has(k))m.set(k,[]);m.get(k).push(r);}return [...m].map(([key,rs])=>({key,...stats(rs)}));}
function months(start,end){if(!start||!end||start>end)return[];let d=new Date(start.slice(0,7)+'-01T00:00:00Z'),last=end.slice(0,7),out=[];for(let i=0;i<2400&&d.toISOString().slice(0,7)<=last;i++){out.push(d.toISOString().slice(0,7));d.setUTCMonth(d.getUTCMonth()+1);}return out;}
function monthly(rows,start,end){const g=new Map(group(rows,r=>r.date.slice(0,7)).map(r=>[r.key,r]));return months(start,end).map(key=>g.get(key)||{key,...stats([])});}
function decompose(a,b){if(!a.count||!b.count)return null;const countEffect=(b.count-a.count)*(a.aov+b.aov)/2,valueEffect=(b.aov-a.aov)*(a.count+b.count)/2;return {countEffect,valueEffect,change:b.revenue-a.revenue};}
function search(rows,q){q=q.trim().toLowerCase();return q?rows.filter(r=>[r.id,r.date,r.customer,r.category].some(x=>String(x).toLowerCase().includes(q))):rows;}
function csv(rows){const safe=x=>'"'+String(x).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';return [columns.map(safe).join(','),...rows.map(r=>[r.id,r.date,r.customer,r.gender,r.age,r.category,r.quantity,r.price,r.amount].map(safe).join(','))].join('\r\n');}
const api={parseCSV,validate,filter,stats,group,monthly,decompose,search,csv,columns};if(typeof module!=='undefined')module.exports=api;root.Retail=api;
})(typeof globalThis!=='undefined'?globalThis:this);
